'use strict';
// Shared atlas reader. Sheets keep explicit grids; gameplay uses stable foot anchors.
class PixelAtlas {
 constructor(src,columns,rows,logicalWidth,logicalHeight,trim=true){this.ready=false;this.frames=[];this.columns=columns;this.rows=rows;this.image=new Image();this.image.onload=()=>{const c=document.createElement('canvas');c.width=this.image.naturalWidth;c.height=this.image.naturalHeight;const g=c.getContext('2d',{willReadFrequently:true});g.drawImage(this.image,0,0);for(let i=0;i<columns*rows;i++){const x=Math.round(i%columns*c.width/columns),y=Math.round(Math.floor(i/columns)*c.height/rows),w=Math.round((i%columns+1)*c.width/columns)-x,h=Math.round((Math.floor(i/columns)+1)*c.height/rows)-y;let l=0,t=0,r=w-1,b=h-1;if(trim){l=w;t=h;r=-1;b=-1;const data=g.getImageData(x,y,w,h).data;for(let py=0;py<h;py++)for(let px=0;px<w;px++)if(data[(py*w+px)*4+3]>=160){l=Math.min(l,px);r=Math.max(r,px);t=Math.min(t,py);b=Math.max(b,py);}}const f=document.createElement('canvas');if(r<l||b<t){f.width=logicalWidth;f.height=logicalHeight;}else{const ratio=Math.min(logicalWidth/(r-l+1),logicalHeight/(b-t+1));f.width=trim?Math.max(1,Math.round((r-l+1)*ratio)):logicalWidth;f.height=trim?Math.max(1,Math.round((b-t+1)*ratio)):logicalHeight;const fg=f.getContext('2d');fg.imageSmoothingEnabled=false;fg.drawImage(c,x+l,y+t,r-l+1,b-t+1,0,0,f.width,f.height);}this.frames.push(f);}this.ready=true;document.dispatchEvent(new Event('mosswild-art-ready'));};this.image.onerror=()=>{this.failed=true;};this.image.src=src;}
 draw(g,index,x,y,height,width,flip=false){if(!this.ready||!this.frames[index])return false;const f=this.frames[index];width=width||Math.round(height*f.width/f.height);g.save();g.imageSmoothingEnabled=false;if(flip){g.translate(Math.round(x),Math.round(y));g.scale(-1,1);g.drawImage(f,-Math.round(width/2),-height,width,height);}else g.drawImage(f,Math.round(x-width/2),Math.round(y-height),width,height);g.restore();return true;}
 tile(g,index,x,y,width=32,height=32){return this.draw(g,index,x+width/2,y+height,height,width);}
}
const PlayerPixels=new PixelAtlas('assets/rounded-characters.png',4,2,64,96);
const CompanionPixels=new PixelAtlas('assets/companions.png',6,3,64,64);
const companionArtNames=['Pip','Emberkin','Dewdrop','Lunamoth','Bramble','Talus','Fennel','Pearl','Nova'];
function drawCompanionPixels(g,name,x,y,height=22,dir=0,walk=0){const index=companionArtNames.indexOf(name);if(index<0)return false;const side=dir===1||dir===2,facesRight=['Emberkin','Bramble','Pearl','Nova'].includes(name),flip=side&&((dir===2)!==facesRight);return CompanionPixels.draw(g,index*2+(side?1:0),x,y+(walk?Math.round(Math.sin(walk)):0),height,undefined,flip);}
